  "headline": "Fentanyl citrate injection shortage stems from long-standing FDA regulatory actions at Hospira and Hikma manufacturing sites",
  "headline_cites": ["E17", "E25"],
  "sentences": [
    {
      "text": "FDA first posted the fentanyl citrate injection shortage on 2012-01-01 and it remains current as of 2026-10-21.",
      "cites": ["E29", "E14"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) has been listed on the FDA shortage list since the initial 2012-01-01 posting with a current status updated 2026-10-08.",
      "cites": ["E28"]
    },
    {
      "text": "FDA inspections at the Hospira plant resulted in OAI classifications on 2010-01-19, 2011-06-17, and 2011-08-04, and a Warning Letter was issued on 2010-04-12.",
      "cites": ["E9", "E10", "E11", "E16"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. (FEI 2220525) was added to the FDA shortage list on 2023-12-20 with current status updated 2026-10-14.",
      "cites": ["E27"]
    },
    {
      "text": "FDA inspections at the Hikma plant have shown VAI classifications from 2009-03-10 through the most recent on 2024-06-12.",
      "cites": ["E18", "E19", "E20", "E21", "E22", "E23", "E24"]
    },
    {
      "text": "Corvale East holds 144 units of Hospira fentanyl citrate (NDC 00409909422) with 18.0 daily use, while Corvale General holds 348 units of the same product with 19.3 daily use.",
      "cites": ["E1", "E5"]
    }
  ]
}
